from fractions import Fraction

def sample_covariance2(rows):
    if type(rows) is not list or not 2 <= len(rows) <= 1000:
        raise ValueError("expected 2..1000 complete paired observations")
    if any(type(row) is not list or len(row) != 2 for row in rows):
        raise ValueError("expected exactly two coordinates per row")
    if any(type(x) is not int or abs(x) > 1000000 for row in rows for x in row):
        raise ValueError("expected bounded integer coordinates, excluding bool")
    means = [Fraction(sum(row[j] for row in rows),len(rows)) for j in range(2)]
    centered = [[x-mean for x,mean in zip(row,means)] for row in rows]
    return [[sum(row[i]*row[j] for row in centered)/(len(rows)-1)
             for j in range(2)] for i in range(2)]

covariance = sample_covariance2([[1,2],[2,4],[3,6]])
print([[str(x) for x in row] for row in covariance])
direction = [2,-1]
print(sum(direction[i]*covariance[i][j]*direction[j]
          for i in range(2) for j in range(2)))

from math import sqrt

def cholesky2_demo(matrix):
    if type(matrix) is not list or len(matrix) != 2 or any(type(row) is not list or len(row) != 2 for row in matrix):
        raise ValueError("expected2x2list matrix")
    if any(type(x) is not int or abs(x) > 1000000
           for row in matrix for x in row):
        raise ValueError("expected bounded integer entries, excluding bool")
    if matrix[0][1] != matrix[1][0]:
        raise ValueError("this demonstration requires exact input symmetry")
    if matrix[0][0] <= 0:
        raise ValueError("nonpositive first pivot")
    # Exact integer determinant check avoids a rounded positive pivot for singular input.
    determinant = matrix[0][0]*matrix[1][1] - matrix[0][1]*matrix[1][0]
    if determinant <= 0:
        raise ValueError("nonpositive determinant")
    first = sqrt(matrix[0][0])
    lower = matrix[1][0] / first
    last_squared = matrix[1][1] - lower*lower
    if last_squared <= 0:
        raise ValueError("nonpositive remaining pivot")
    return [[first,0.0],[lower,sqrt(last_squared)]]

matrix = [[4,2],[2,3]]
lower = cholesky2_demo(matrix)
print([[round(x,6) for x in row] for row in lower])
rebuilt = [[sum(lower[i][k]*lower[j][k] for k in range(2))
            for j in range(2)] for i in range(2)]
print(all(abs(rebuilt[i][j]-matrix[i][j]) <= 1e-12 for i in range(2) for j in range(2)))
for bad in ([[1,2],[2,4]], [[1,2],[2,1]], [[4,9],[2,3]]):
    try:
        cholesky2_demo(bad)
    except ValueError:
        print("rejected")
